import java.util.Scanner;

public class StudentMarksheet {
    private String name;
    private int roll;
    private double sub1, sub2, sub3, total, percentage;
    private String grade;

    public void accept() {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter Student Name: ");
        name = sc.nextLine();
        System.out.print("Enter Roll Number : ");
        roll = sc.nextInt();
        System.out.print("Enter Marks in Subject 1: ");
        sub1 = sc.nextDouble();
        System.out.print("Enter Marks in Subject 2: ");
        sub2 = sc.nextDouble();
        System.out.print("Enter Marks in Subject 3: ");
        sub3 = sc.nextDouble();
    }

    public void compute() {
        total = sub1 + sub2 + sub3;
        percentage = (total / 300.0) * 100.0;

        if (percentage >= 90.0) grade = "Pass with Distinction";
        else if (percentage >= 75.0) grade = "First Class";
        else if (percentage >= 50.0) grade = "Second Class";
        else grade = "Needs Improvement";
    }

    public void display() {
        System.out.println("\n========================================");
        System.out.println("           STUDENT REPORT CARD          ");
        System.out.println("========================================");
        System.out.println("Roll Number : " + roll);
        System.out.println("Student Name: " + name);
        System.out.printf("Total Marks : %.1f / 300\n", total);
        System.out.printf("Percentage  : %.2f%%\n", percentage);
        System.out.println("Grade Award : " + grade);
        System.out.println("========================================");
    }

    public static void main(String[] args) {
        StudentMarksheet report = new StudentMarksheet();
        report.accept();
        report.compute();
        report.display();
    }
}
```

