import java.util.Scanner;

public class ArrayMergeTen {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] A = new int[5];
        int[] B = new int[5];
        int[] C = new int[10];

        System.out.println("Enter 5 integers for Array A:");
        for (int i = 0; i < 5; i++) {
            System.out.print("A[" + i + "]: ");
            A[i] = sc.nextInt();
        }

        System.out.println("Enter 5 integers for Array B:");
        for (int i = 0; i < 5; i++) {
            System.out.print("B[" + i + "]: ");
            B[i] = sc.nextInt();
        }

        // Merging
        for (int i = 0; i < 5; i++) {
            C[i] = A[i];
            C[i + 5] = B[i];
        }

        System.out.print("\nMerged Array C: ");
        int sum = 0;
        for (int val : C) {
            System.out.print(val + " ");
            sum += val;
        }

        double avg = (double) sum / C.length;
        System.out.printf("\nSum = %d, Average = %.2f\n", sum, avg);
    }
}
```

