import java.util.Scanner;

public class MatrixTranspose {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[][] mat = new int[3][3];
        int[][] trans = new int[3][3];

        System.out.println("Enter 9 elements for 3x3 matrix:");
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                System.out.print("mat[" + i + "][" + j + "]: ");
                mat[i][j] = sc.nextInt();
                trans[j][i] = mat[i][j]; // Transposing
            }
        }

        System.out.println("\n--- Original Matrix ---");
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) System.out.print(mat[i][j] + "\t");
            System.out.println();
        }

        System.out.println("\n--- Transposed Matrix ---");
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) System.out.print(trans[i][j] + "\t");
            System.out.println();
        }
    }
}
```

