public class ComputeOverloading {
    public void compute(int n) {
        int temp = Math.abs(n);
        int sum = 0;
        while (temp > 0) {
            sum += temp % 10;
            temp /= 10;
        }
        System.out.println("Sum of digits of " + n + " = " + sum);
    }

    public void compute(String s) {
        int vowels = 0;
        String upper = s.toUpperCase();
        for (int i = 0; i < upper.length(); i++) {
            char c = upper.charAt(i);
            if (c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U') vowels++;
        }
        System.out.println("Vowel count in \"" + s + "\" = " + vowels);
    }

    public void compute(double r) {
        double area = (22.0 / 7.0) * r * r;
        System.out.printf("Area of Circle (r=%.2f) = %.2f sq. units\n", r, area);
    }

    public static void main(String[] args) {
        ComputeOverloading obj = new ComputeOverloading();
        obj.compute(4928);
        obj.compute("ICSE Board Java");
        obj.compute(7.0);
    }
}
```

